declare const _default: "if (typeof globalThis.Headers === 'undefined') {\nclass Headers {\n  constructor(init) {\n    this.map = {};\n\n    if (init instanceof Headers) {\n        init.forEach((value, name) => {\n            this.append(name, value);\n        });\n    } else if (init) {\n        Object.getOwnPropertyNames(init).forEach(name => {\n            this.append(name, init[name]);\n        });\n    }\n  }\n\n  append(name, value) {\n    name = name.toLowerCase();\n    if (this.map[name]) {\n        this.map[name].push(value);\n    } else {\n        this.map[name] = [value];\n    }\n  }\n\n  delete(name) {\n    delete this.map[name.toLowerCase()];\n  }\n\n  get(name) {\n    name = name.toLowerCase();\n    return this.map[name] ? this.map[name][0] : null;\n  }\n\n  getAll(name) {\n    return this.map[name.toLowerCase()] || [];\n  }\n\n  has(name) {\n    return this.map.hasOwnProperty(name.toLowerCase());\n  }\n\n  set(name, value) {\n    this.map[name.toLowerCase()] = [value];\n  }\n  \n  forEach(callback, thisArg) {\n    Object.getOwnPropertyNames(this.map).forEach(name => {\n        this.map[name].forEach(value => {\n            callback.call(thisArg, value, name, this);\n        });\n    });\n  }\n}\nglobalThis.Headers = Headers;\n}\nexport default globalThis.Headers;\n";
